// Timing-flow stand-in for the I/O island (iocore/rtl/iocore_top.sv) in the
// hart-domain run of upycore/tools/sta/run.py: the same name, parameters and
// ports, with every input ending at a flop and every output starting at
// one, the way the SRAM macros are stubbed. The island runs on io_clk and is
// timed on its own (iocore/tools/island_measure.py); this keeps it out of
// the hart's register groups. Generated by iocore/tools/gen_sta_stub.py.
module iocore_top #(
    parameter int CORE = 0,               // iocore_cpu: 0 CVE2, 1 Hazard3
    parameter int MUL = 0,
    parameter int CODE_WORDS = 4096,      // 16 KB
    parameter int DATA_WORDS = 2048,      // 8 KB
    parameter logic [15:0] US_DIV_RESET = 16'd49,
    parameter logic [15:0] BAUD_RESET = 16'd0,
    parameter int NPINS = 16,
    parameter int IOCLK_HZ = 50_000_000   // SYS FREQ; +IO_CLK_HZ (or the bench's +IO_CLK_NS) overrides it in simulation
) (
    input  logic        io_clk_i,
    input  logic        io_rst_n_i,       // power-on reset, synchronized to io_clk_i
    input  logic        run_i,            // release the core (synchronized here)
    input  logic [1:0]  con_mode_i,       // the console strap (a pin; synchronized here)

    input  logic        ld_valid_i,
    input  logic [48:0] ld_data_i,        // {1 data SRAM / 0 code SRAM, word index, word}
    output logic        ld_pop_o,

    // The bridge FIFOs' io_clk ends (mpy_iobr).
    output logic        cmd_pop_o,
    input  logic [31:0] cmd_data_i,
    input  logic        cmd_empty_i,
    input  logic [5:0]  cmd_level_i,
    output logic        rsp_push_o,
    output logic [31:0] rsp_data_o,
    input  logic        rsp_full_i,
    output logic        evt_push_o,
    output logic [15:0] evt_data_o,
    input  logic        evt_full_i,
    output logic        con_pop_o,
    input  logic [8:0]  con_data_i,
    input  logic        con_empty_i,
    input  logic [6:0]  con_level_i,
    output logic        conrx_push_o,
    output logic [7:0]  conrx_data_o,
    input  logic        conrx_full_i,
    output logic        upd_push_o,
    output logic [36:0] upd_data_o,
    input  logic        upd_full_i,
    output logic        dn_pop_o,
    input  logic [34:0] dn_data_i,
    input  logic        dn_empty_i,

    input  logic        uart_rxd_i,
    output logic        uart_txd_o,

    output logic [NPINS-1:0] gpio_o,
    output logic [NPINS-1:0] gpio_oe_o,
    output logic [NPINS-1:0] gpio_pu_o,
    output logic [NPINS-1:0] gpio_pd_o,
    input  logic [NPINS-1:0] gpio_i,

    // The timer's microsecond and millisecond counts in gray code, from
    // flops, for mpy_iobr's tick crossing (one bit changes per count).
    output logic [31:0] us_gray_o,
    output logic [31:0] ms_gray_o,

    // Simulation and bring-up: a store to SYS DEBUG / HALT.
    output logic        dbg_valid_o,
    output logic [7:0]  dbg_byte_o,
    output logic        halt_o,
    output logic [31:0] halt_value_o,
    output logic        sleep_o
);
    // Inputs end at flops (every bit is a timing endpoint).
    (* keep *) logic q_io_rst_n_i;
    (* keep *) logic q_run_i;
    (* keep *) logic [1:0] q_con_mode_i;
    (* keep *) logic q_ld_valid_i;
    (* keep *) logic [48:0] q_ld_data_i;
    (* keep *) logic [31:0] q_cmd_data_i;
    (* keep *) logic q_cmd_empty_i;
    (* keep *) logic [5:0] q_cmd_level_i;
    (* keep *) logic q_rsp_full_i;
    (* keep *) logic q_evt_full_i;
    (* keep *) logic [8:0] q_con_data_i;
    (* keep *) logic q_con_empty_i;
    (* keep *) logic [6:0] q_con_level_i;
    (* keep *) logic q_conrx_full_i;
    (* keep *) logic q_upd_full_i;
    (* keep *) logic [34:0] q_dn_data_i;
    (* keep *) logic q_dn_empty_i;
    (* keep *) logic q_uart_rxd_i;
    (* keep *) logic [NPINS-1:0] q_gpio_i;
    always_ff @(posedge io_clk_i) begin
        q_io_rst_n_i <= io_rst_n_i;
        q_run_i <= run_i;
        q_con_mode_i <= con_mode_i;
        q_ld_valid_i <= ld_valid_i;
        q_ld_data_i <= ld_data_i;
        q_cmd_data_i <= cmd_data_i;
        q_cmd_empty_i <= cmd_empty_i;
        q_cmd_level_i <= cmd_level_i;
        q_rsp_full_i <= rsp_full_i;
        q_evt_full_i <= evt_full_i;
        q_con_data_i <= con_data_i;
        q_con_empty_i <= con_empty_i;
        q_con_level_i <= con_level_i;
        q_conrx_full_i <= conrx_full_i;
        q_upd_full_i <= upd_full_i;
        q_dn_data_i <= dn_data_i;
        q_dn_empty_i <= dn_empty_i;
        q_uart_rxd_i <= uart_rxd_i;
        q_gpio_i <= gpio_i;
    end
    // Outputs start at flops (their own sources, not the inputs).
    (* keep *) logic r_ld_pop_o;
    always_ff @(posedge io_clk_i) r_ld_pop_o <= r_ld_pop_o + 1'b1;
    assign ld_pop_o = r_ld_pop_o;
    (* keep *) logic r_cmd_pop_o;
    always_ff @(posedge io_clk_i) r_cmd_pop_o <= r_cmd_pop_o + 1'b1;
    assign cmd_pop_o = r_cmd_pop_o;
    (* keep *) logic r_rsp_push_o;
    always_ff @(posedge io_clk_i) r_rsp_push_o <= r_rsp_push_o + 1'b1;
    assign rsp_push_o = r_rsp_push_o;
    (* keep *) logic [31:0] r_rsp_data_o;
    always_ff @(posedge io_clk_i) r_rsp_data_o <= r_rsp_data_o + 1'b1;
    assign rsp_data_o = r_rsp_data_o;
    (* keep *) logic r_evt_push_o;
    always_ff @(posedge io_clk_i) r_evt_push_o <= r_evt_push_o + 1'b1;
    assign evt_push_o = r_evt_push_o;
    (* keep *) logic [15:0] r_evt_data_o;
    always_ff @(posedge io_clk_i) r_evt_data_o <= r_evt_data_o + 1'b1;
    assign evt_data_o = r_evt_data_o;
    (* keep *) logic r_con_pop_o;
    always_ff @(posedge io_clk_i) r_con_pop_o <= r_con_pop_o + 1'b1;
    assign con_pop_o = r_con_pop_o;
    (* keep *) logic r_conrx_push_o;
    always_ff @(posedge io_clk_i) r_conrx_push_o <= r_conrx_push_o + 1'b1;
    assign conrx_push_o = r_conrx_push_o;
    (* keep *) logic [7:0] r_conrx_data_o;
    always_ff @(posedge io_clk_i) r_conrx_data_o <= r_conrx_data_o + 1'b1;
    assign conrx_data_o = r_conrx_data_o;
    (* keep *) logic r_upd_push_o;
    always_ff @(posedge io_clk_i) r_upd_push_o <= r_upd_push_o + 1'b1;
    assign upd_push_o = r_upd_push_o;
    (* keep *) logic [36:0] r_upd_data_o;
    always_ff @(posedge io_clk_i) r_upd_data_o <= r_upd_data_o + 1'b1;
    assign upd_data_o = r_upd_data_o;
    (* keep *) logic r_dn_pop_o;
    always_ff @(posedge io_clk_i) r_dn_pop_o <= r_dn_pop_o + 1'b1;
    assign dn_pop_o = r_dn_pop_o;
    (* keep *) logic r_uart_txd_o;
    always_ff @(posedge io_clk_i) r_uart_txd_o <= r_uart_txd_o + 1'b1;
    assign uart_txd_o = r_uart_txd_o;
    (* keep *) logic [NPINS-1:0] r_gpio_o;
    always_ff @(posedge io_clk_i) r_gpio_o <= r_gpio_o + 1'b1;
    assign gpio_o = r_gpio_o;
    (* keep *) logic [NPINS-1:0] r_gpio_oe_o;
    always_ff @(posedge io_clk_i) r_gpio_oe_o <= r_gpio_oe_o + 1'b1;
    assign gpio_oe_o = r_gpio_oe_o;
    (* keep *) logic [NPINS-1:0] r_gpio_pu_o;
    always_ff @(posedge io_clk_i) r_gpio_pu_o <= r_gpio_pu_o + 1'b1;
    assign gpio_pu_o = r_gpio_pu_o;
    (* keep *) logic [NPINS-1:0] r_gpio_pd_o;
    always_ff @(posedge io_clk_i) r_gpio_pd_o <= r_gpio_pd_o + 1'b1;
    assign gpio_pd_o = r_gpio_pd_o;
    (* keep *) logic [31:0] r_us_gray_o;
    always_ff @(posedge io_clk_i) r_us_gray_o <= r_us_gray_o + 1'b1;
    assign us_gray_o = r_us_gray_o;
    (* keep *) logic [31:0] r_ms_gray_o;
    always_ff @(posedge io_clk_i) r_ms_gray_o <= r_ms_gray_o + 1'b1;
    assign ms_gray_o = r_ms_gray_o;
    (* keep *) logic r_dbg_valid_o;
    always_ff @(posedge io_clk_i) r_dbg_valid_o <= r_dbg_valid_o + 1'b1;
    assign dbg_valid_o = r_dbg_valid_o;
    (* keep *) logic [7:0] r_dbg_byte_o;
    always_ff @(posedge io_clk_i) r_dbg_byte_o <= r_dbg_byte_o + 1'b1;
    assign dbg_byte_o = r_dbg_byte_o;
    (* keep *) logic r_halt_o;
    always_ff @(posedge io_clk_i) r_halt_o <= r_halt_o + 1'b1;
    assign halt_o = r_halt_o;
    (* keep *) logic [31:0] r_halt_value_o;
    always_ff @(posedge io_clk_i) r_halt_value_o <= r_halt_value_o + 1'b1;
    assign halt_value_o = r_halt_value_o;
    (* keep *) logic r_sleep_o;
    always_ff @(posedge io_clk_i) r_sleep_o <= r_sleep_o + 1'b1;
    assign sleep_o = r_sleep_o;
endmodule
